692	new file mode 100644
693	index 0000000000..fbb1d48fe0
694	--- /dev/null
695	+++ b/cmd/entire/cli/session_auto_adopt.go
696	@@ -0,0 +1,481 @@
697	+package cli
698	+
699	+import (
700	+	"context"
701	+	"fmt"
702	+	"log/slog"
703	+	"os"
704	+	"os/exec"
705	+	"path/filepath"
706	+	"strings"
707	+	"time"
708	+
709	+	"github.com/entireio/cli/cmd/entire/cli/logging"
710	+	"github.com/entireio/cli/cmd/entire/cli/paths"
711	+	"github.com/entireio/cli/cmd/entire/cli/proclive"
712	+	"github.com/entireio/cli/cmd/entire/cli/session"
713	+	"github.com/entireio/cli/cmd/entire/cli/settings"
714	+	"github.com/entireio/cli/cmd/entire/cli/strategy"
715	+)
716	+
717	+// maxSiblingAutoAdoptScan caps how many sibling directories prepare-commit-msg will
718	+// inspect when the live-session registry has no unique candidate. Keeps the
719	+// hook bounded on large parent directories.
720	+const maxSiblingAutoAdoptScan = 32
721	+
722	+// Time bounds for prepare-commit-msg auto-adopt. Sibling git rev-parse calls
723	+// use CommandContext; without a deadline a hung network mount could block
724	+// `git commit` indefinitely.
725	+const (
726	+	autoAdoptSiblingScanTimeout = 2 * time.Second
727	+	autoAdoptGitResolveTimeout  = 500 * time.Millisecond
728	+	autoAdoptStagedFilesTimeout = 1 * time.Second
729	+)
730	+
731	+// prepareCommitMsgSourceAmend is git's prepare-commit-msg source for `git commit --amend`.
732	+const prepareCommitMsgSourceAmend = "commit"
733	+
734	+// shouldTryAutoAdoptOnPrepareCommitMsg reports whether prepare-commit-msg should
735	+// attempt cross-common-dir auto-adopt. Matches ManualCommitStrategy.PrepareCommitMsg
736	+// skip conditions so we never retire a live session when no trailer would be written.
737	+// Amend (source "commit"): handleAmendCommitMsg only restores an existing trailer /
738	+// HEAD LastCheckpointID match and will not write a trailer for a freshly adopted session.
739	+func shouldTryAutoAdoptOnPrepareCommitMsg(ctx context.Context, source string) bool {
740	+	switch source {
741	+	case "merge", "squash", prepareCommitMsgSourceAmend:
742	+		return false
743	+	}
744	+	return !strategy.IsGitSequenceOperation(ctx)
745	+}
746	+
747	+// tryAutoAdoptCrossCommonDirSession adopts a unique ACTIVE session from another
748	+// git common dir into the current worktree when it is safe to do so.
749	+//
750	+// Discovery order:
751	+//  1. Live-session registry (written on ACTIVE StateStore.Save), limited to
752	+//     worktrees that share the target's parent directory (same proximity as #2)
753	+//  2. Immediate sibling repos under the parent directory (seeded / microservices)
754	+//
755	+// A candidate is accepted only when exactly one match remains after filtering
756	+// for recent ACTIVE sessions that (a) share the committing process owner and
757	+// (b) have FilesTouched overlapping the staged commit paths on a
758	+// non-boilerplate relative path (README.md / go.mod / package.json / … alone
759	+// never count). Registry entries also require sibling proximity. Idle sessions
760	+// are never auto-adopted. Ambiguity skips.
761	+//
762	+// Best-effort: never returns an error to the git hook caller.
763	+func tryAutoAdoptCrossCommonDirSession(ctx context.Context) {
764	+	logCtx := logging.WithComponent(ctx, "session")
765	+
766	+	if !targetIsEntireEnabled(ctx) {
767	+		return
768	+	}
769	+
770	+	targetWorktree, err := paths.WorktreeRoot(ctx)
771	+	if err != nil || targetWorktree == "" {
772	+		return
773	+	}
774	+	targetStore, _, targetCommonDir, err := stateStoreForWorktree(ctx, targetWorktree)
775	+	if err != nil {
776	+		return
777	+	}
778	+	if hasLocalActiveSession(ctx, targetStore) {
779	+		return
780	+	}
781	+
782	+	stagedCtx, stagedCancel := context.WithTimeout(ctx, autoAdoptStagedFilesTimeout)
783	+	staged, err := stagedFilesForAutoAdopt(stagedCtx, targetWorktree)
784	+	stagedCancel()
785	+	if err != nil {
786	+		staged = nil
787	+	}
788	+	// Owner + staged overlap are both required for every candidate. Bail before
789	+	// any registry/sibling I/O when either is missing (ordinary human commits).
790	+	if len(staged) == 0 {
791	+		return
792	+	}
793	+	owner, hasOwner := proclive.ResolveOwner()
794	+	if !hasOwner {
795	+		return
796	+	}
797	+
798	+	candidates := collectRegistryAutoAdoptCandidates(ctx, targetWorktree, targetCommonDir, staged, owner, hasOwner)
799	+	if len(candidates) == 0 {
800	+		scanCtx, scanCancel := context.WithTimeout(ctx, autoAdoptSiblingScanTimeout)
801	+		candidates = collectSiblingAutoAdoptCandidates(scanCtx, targetWorktree, targetCommonDir, staged, owner, hasOwner)
802	+		scanCancel()
803	+	}
804	+	if len(candidates) != 1 {
805	+		if len(candidates) > 1 {
806	+			logging.Debug(logCtx, "auto-adopt: skipped ambiguous cross-common-dir sessions",
807	+				slog.Int("candidates", len(candidates)),
808	+			)
809	+		}
810	+		return
811	+	}
812	+
813	+	source := candidates[0]
814	+	existing, err := targetStore.Load(ctx, source.SessionID)
815	+	if err != nil || existing != nil {
816	+		return
817	+	}
818	+
819	+	logging.Info(logCtx, "auto-adopt: adopting cross-common-dir session for commit",
820	+		slog.String("session_id", source.SessionID),
821	+		slog.String("from_worktree", source.WorktreePath),
822	+		slog.String("to_worktree", targetWorktree),
823	+	)
824	+
825	+	_, _, adoptErr := adoptFromExternalSessionStore(
826	+		ctx,
827	+		source.Store,
828	+		source.WorktreePath,
829	+		source.CommonDir,
830	+		targetStore,
831	+		targetCommonDir,
832	+		source.SessionID,
833	+		adoptOptions{Force: true, SkipTranscriptValidation: true},
834	+	)
835	+	if adoptErr != nil {
836	+		logging.Debug(logCtx, "auto-adopt: adopt failed",
837	+			slog.String("session_id", source.SessionID),
838	+			slog.String("error", adoptErr.Error()),
839	+		)
840	+	}
841	+}
842	+
843	+type autoAdoptCandidate struct {
844	+	SessionID    string
845	+	WorktreePath string
846	+	CommonDir    string
847	+	Store        *session.StateStore
848	+	OwnerMatch   bool
849	+	OverlapMatch bool
850	+}
851	+
852	+func hasLocalActiveSession(ctx context.Context, store *session.StateStore) bool {
853	+	states, err := store.List(ctx)
854	+	if err != nil {
855	+		return true // fail closed: do not steal when local store is unreadable
856	+	}
857	+	for _, state := range states {
858	+		if isAdoptableSourceSession(state) {
859	+			return true
860	+		}
861	+	}
862	+	return false
863	+}
864	+
865	+func collectRegistryAutoAdoptCandidates(
866	+	ctx context.Context,
867	+	targetWorktree, targetCommonDir string,
868	+	staged []string,
869	+	owner proclive.Identity,
870	+	hasOwner bool,
871	+) []autoAdoptCandidate {
872	+	entries, err := session.ListLiveSessions()
873	+	if err != nil || len(entries) == 0 {
874	+		return nil
875	+	}
876	+
877	+	var out []autoAdoptCandidate
878	+	for _, entry := range entries {
879	+		if sameAdoptStore(entry.CommonDir, targetCommonDir) {
880	+			continue
881	+		}
882	+		if !isRecentLiveEntry(entry) {
883	+			continue
884	+		}
885	+		// Same parent-dir proximity as the sibling scan. Without this, a shared
886	+		// owner (tmux/IDE) + common relative filename can steal across unrelated repos.
887	+		if !autoAdoptSiblingProximity(entry.WorktreePath, targetWorktree) {
888	+			continue
889	+		}
890	+		cand, ok := candidateFromSource(ctx, entry.WorktreePath, entry.SessionID, staged, owner, hasOwner)
891	+		if ok {
892	+			out = append(out, cand)
893	+		}
894	+	}
895	+	return out
896	+}
897	+
898	+func collectSiblingAutoAdoptCandidates(
899	+	ctx context.Context,
900	+	targetWorktree, targetCommonDir string,
901	+	staged []string,
902	+	owner proclive.Identity,
903	+	hasOwner bool,
904	+) []autoAdoptCandidate {
905	+	parent := filepath.Dir(targetWorktree)
906	+	if parent == "" || parent == targetWorktree {
907	+		return nil
908	+	}
909	+	entries, err := os.ReadDir(parent)
910	+	if err != nil {
911	+		return nil
912	+	}
913	+
914	+	var out []autoAdoptCandidate
915	+	scanned := 0
916	+	for _, entry := range entries {
917	+		if scanned >= maxSiblingAutoAdoptScan {
918	+			break
919	+		}
920	+		if !entry.IsDir() {
921	+			continue
922	+		}
923	+		sibling := filepath.Join(parent, entry.Name())
924	+		if sameAdoptPath(sibling, targetWorktree) {
925	+			continue
926	+		}
927	+		// Cheap pre-filters before shelling out to git rev-parse:
928	+		//  1. .git entry (skip node_modules / build outputs)
929	+		//  2. .entire/ (skip git repos that don't use Entire — no sessions to adopt)
930	+		if !siblingLooksLikeGitWorktree(sibling) || !siblingLooksLikeEntireRepo(sibling) {
931	+			continue
932	+		}
933	+		scanned++
934	+
935	+		resolveCtx, resolveCancel := context.WithTimeout(ctx, autoAdoptGitResolveTimeout)
936	+		store, worktree, commonDir, err := stateStoreForWorktree(resolveCtx, sibling)
937	+		resolveCancel()
938	+		if err != nil || sameAdoptStore(commonDir, targetCommonDir) {
939	+			continue
940	+		}
941	+		states, err := store.List(ctx)
942	+		if err != nil {
943	+			continue
944	+		}
945	+		for _, state := range states {
946	+			if !isRecentAdoptCandidate(state) {
947	+				continue
948	+			}
949	+			cand, ok := candidateFromLoaded(store, worktree, commonDir, state, staged, owner, hasOwner)
950	+			if ok {
951	+				out = append(out, cand)
952	+			}
953	+		}
954	+	}
955	+	return out
956	+}
957	+
958	+func candidateFromSource(
959	+	ctx context.Context,
960	+	sourceWorktree, sessionID string,
961	+	staged []string,
962	+	owner proclive.Identity,
963	+	hasOwner bool,
964	+) (autoAdoptCandidate, bool) {
965	+	store, worktree, commonDir, err := stateStoreForWorktree(ctx, sourceWorktree)
966	+	if err != nil {
967	+		return autoAdoptCandidate{}, false
968	+	}
969	+	state, err := store.Load(ctx, sessionID)
970	+	if err != nil || state == nil {
971	+		return autoAdoptCandidate{}, false
972	+	}
973	+	return candidateFromLoaded(store, worktree, commonDir, state, staged, owner, hasOwner)
974	+}
975	+
976	+func candidateFromLoaded(
977	+	store *session.StateStore,
978	+	worktree, commonDir string,
979	+	state *session.State,
980	+	staged []string,
981	+	owner proclive.Identity,
982	+	hasOwner bool,
983	+) (autoAdoptCandidate, bool) {
984	+	if !isRecentAdoptCandidate(state) {
985	+		return autoAdoptCandidate{}, false
986	+	}
987	+	// Auto-adopt is ACTIVE-only (matches live-registry prefilter and the feature doc).
988	+	// Idle is adoptable manually but must not be silently relocated on a commit hook.
989	+	if state.Phase != session.PhaseActive {
990	+		return autoAdoptCandidate{}, false
991	+	}
992	+	// Reject stale WorktreePath mismatches. Overriding worktree with
993	+	// state.WorktreePath would make sessionBelongsToSourceWorktree a tautology
994	+	// (comparing the recorded path against itself) and miss the ownership check.
995	+	if state.WorktreePath != "" && !sameAdoptPath(state.WorktreePath, worktree) {
996	+		return autoAdoptCandidate{}, false
997	+	}
998	+	// Both owner match and distinctive FilesTouched overlap are required.
999	+	// Boilerplate-only overlap (README.md, go.mod, …) is ignored even when
1000	+	// the owner matches — those names collide across unrelated siblings.
1001	+	overlapMatch := filesTouchedOverlap(state.FilesTouched, staged)
1002	+	if !overlapMatch {
1003	+		return autoAdoptCandidate{}, false
1004	+	}
1005	+	ownerMatch := hasOwner && ownerMatches(state.Owner, owner)
1006	+	if !ownerMatch {
1007	+		return autoAdoptCandidate{}, false
1008	+	}
1009	+	return autoAdoptCandidate{
1010	+		SessionID:    state.SessionID,
1011	+		WorktreePath: worktree,
1012	+		CommonDir:    commonDir,
1013	+		Store:        store,
1014	+		OwnerMatch:   ownerMatch,
1015	+		OverlapMatch: overlapMatch,
1016	+	}, true
1017	+}
1018	+
1019	+func isRecentLiveEntry(entry session.LiveSessionEntry) bool {
1020	+	if entry.Phase != session.PhaseActive {
1021	+		return false
1022	+	}
1023	+	if entry.LastInteractionTime == nil {
1024	+		return false
1025	+	}
1026	+	// LiveSessionMaxAge matches adoptRecentWindow; registry TTL sweep uses the same bound.
1027	+	return time.Since(*entry.LastInteractionTime) <= session.LiveSessionMaxAge
1028	+}
1029	+
1030	+// siblingLooksLikeGitWorktree reports whether dir has a .git entry (directory,
1031	+// gitfile, or symlink) so we can skip non-repos before spawning git.
1032	+func siblingLooksLikeGitWorktree(dir string) bool {
1033	+	_, err := os.Lstat(filepath.Join(dir, ".git"))
1034	+	return err == nil
1035	+}
1036	+
1037	+// siblingLooksLikeEntireRepo reports whether dir has a .entire/ directory
1038	+// (written by `entire enable`). Non-Entire siblings have nothing to adopt.
1039	+func siblingLooksLikeEntireRepo(dir string) bool {
1040	+	_, err := os.Lstat(filepath.Join(dir, ".entire"))
1041	+	return err == nil
1042	+}
1043	+
1044	+// autoAdoptSiblingProximity reports whether source and target worktrees share a
1045	+// parent directory (the same bound used by collectSiblingAutoAdoptCandidates).
1046	+func autoAdoptSiblingProximity(sourceWorktree, targetWorktree string) bool {
1047	+	if sourceWorktree == "" || targetWorktree == "" {
1048	+		return false
1049	+	}
1050	+	srcParent := filepath.Dir(sourceWorktree)
1051	+	tgtParent := filepath.Dir(targetWorktree)
1052	+	if srcParent == "" || tgtParent == "" || srcParent == sourceWorktree || tgtParent == targetWorktree {
1053	+		return false
1054	+	}
1055	+	return sameAdoptPath(srcParent, tgtParent)
1056	+}
1057	+
1058	+func ownerMatches(recorded *proclive.Identity, current proclive.Identity) bool {
1059	+	if recorded == nil || recorded.PID == 0 || current.PID == 0 {
1060	+		return false
1061	+	}
1062	+	if recorded.PID != current.PID || recorded.Start != current.Start {
1063	+		return false
1064	+	}
1065	+	// Boot mismatch means a reboot; Start is only unique within a single boot
1066	+	// (same guard as proclive.Check).
1067	+	if recorded.Boot != "" && current.Boot != "" && recorded.Boot != current.Boot {
1068	+		return false
1069	+	}
1070	+	if recorded.Host != "" && current.Host != "" && recorded.Host != current.Host {
1071	+		return false
1072	+	}
1073	+	return true
1074	+}
1075	+
1076	+// autoAdoptBoilerplateBasenames are relative-path basenames that commonly exist
1077	+// in every sibling repo. A match on these alone is not evidence the agent was
1078	+// working on the commit's real change set.
1079	+var autoAdoptBoilerplateBasenames = map[string]struct{}{
1080	+	"readme":              {},
1081	+	"readme.md":           {},
1082	+	"readme.rst":          {},
1083	+	"readme.txt":          {},
1084	+	"license":             {},
1085	+	"license.md":          {},
1086	+	"copying":             {},
1087	+	"changelog.md":        {},
1088	+	"contributing.md":     {},
1089	+	"codeowners":          {},
1090	+	".gitignore":          {},
1091	+	".gitattributes":      {},
1092	+	".editorconfig":       {},
1093	+	".env":                {},
1094	+	".env.example":        {},
1095	+	".nvmrc":              {},
1096	+	".node-version":       {},
1097	+	"go.mod":              {},
1098	+	"go.sum":              {},
1099	+	"package.json":        {},
1100	+	"package-lock.json":   {},
1101	+	"yarn.lock":           {},
1102	+	"pnpm-lock.yaml":      {},
1103	+	"cargo.toml":          {},
1104	+	"cargo.lock":          {},
1105	+	"gemfile":             {},
1106	+	"gemfile.lock":        {},
1107	+	"makefile":            {},
1108	+	"dockerfile":          {},
1109	+	"docker-compose.yml":  {},
1110	+	"docker-compose.yaml": {},
1111	+	"tsconfig.json":       {},
1112	+	"jsconfig.json":       {},
1113	+	"pyproject.toml":      {},
1114	+	"requirements.txt":    {},
1115	+	"setup.py":            {},
1116	+	"setup.cfg":           {},
1117	+	"pipfile":             {},
1118	+	"pipfile.lock":        {},
1119	+	"composer.json":       {},
1120	+	"composer.lock":       {},
1121	+}
1122	+
1123	+func filesTouchedOverlap(touched, staged []string) bool {
1124	+	if len(touched) == 0 || len(staged) == 0 {
1125	+		return false
1126	+	}
1127	+	stagedSet := make(map[string]struct{}, len(staged))
1128	+	for _, f := range staged {
1129	+		stagedSet[filepath.ToSlash(filepath.Clean(f))] = struct{}{}
1130	+	}
1131	+	for _, f := range touched {
1132	+		key := filepath.ToSlash(filepath.Clean(f))
1133	+		if _, ok := stagedSet[key]; !ok {
1134	+			continue
1135	+		}
1136	+		if isAutoAdoptBoilerplatePath(key) {
1137	+			continue
1138	+		}
1139	+		return true
1140	+	}
1141	+	return false
1142	+}
1143	+
1144	+func isAutoAdoptBoilerplatePath(rel string) bool {
1145	+	base := strings.ToLower(filepath.Base(rel))
1146	+	_, ok := autoAdoptBoilerplateBasenames[base]
1147	+	return ok
1148	+}
