1150	+func stagedFilesForAutoAdopt(ctx context.Context, repoRoot string) ([]string, error) {
1151	+	cmd := exec.CommandContext(ctx, "git", "diff", "--cached", "--name-only")
1152	+	cmd.Dir = repoRoot
1153	+	output, err := cmd.Output()
1154	+	if err != nil {
1155	+		return nil, fmt.Errorf("git diff --cached --name-only: %w", err)
1156	+	}
1157	+	trimmed := strings.TrimSpace(string(output))
1158	+	trimmed = strings.ReplaceAll(trimmed, "\r\n", "\n")
1159	+	if trimmed == "" {
1160	+		return nil, nil
1161	+	}
1162	+	var staged []string
1163	+	for _, line := range strings.Split(trimmed, "\n") {
1164	+		if line != "" {
1165	+			staged = append(staged, filepath.ToSlash(line))
1166	+		}
1167	+	}
1168	+	return staged, nil
1169	+}
