1171	+func targetIsEntireEnabled(ctx context.Context) bool {
1172	+	stngs, err := settings.Load(ctx)
1173	+	if err != nil || stngs == nil {
1174	+		return false
1175	+	}
1176	+	return stngs.Enabled
1177	+}
