65	func (s *ManualCommitStrategy) listAllSessionStates(ctx context.Context) ([]*SessionState, error) {
66		store, err := s.getStateStore(ctx)
67		if err != nil {
68			return nil, fmt.Errorf("failed to get state store: %w", err)
69		}
70	
71		sessionStates, err := store.List(ctx)
72		if err != nil {
