74		}
75	
76		if len(sessionStates) == 0 {
77			return nil, nil
78		}
79	
80		repo, err := OpenRepository(ctx)
81		if err != nil {
82			return nil, fmt.Errorf("failed to open git repository: %w", err)
83		}
84		defer repo.Close()
85	
86		var states []*SessionState
87		for _, sessionState := range sessionStates {
88			state := sessionState
89			// Adopted-away source records are tombstones: keep them until normal stale
90			// expiry so old source hooks cannot recreate a second live state.
91			if state.AdoptedIntoWorktreePath != "" {
92				states = append(states, state)
93				continue
94			}
95	
96			// Imported sessions are read-only historical records: no shadow branch
97			// and (by design) no BaseCommit. Keep them regardless of the
98			// shadow-branch orphan check below. Gate on Kind, not on commit
99			// presence, so this stays correct once imports are linked to a commit.
100			if state.Kind.IsImported() {
101				states = append(states, state)
102				continue
103			}
104	
105			// Skip and cleanup orphaned sessions whose shadow branch no longer exists.
106			// Keep active sessions (shadow branch may not be created yet) and sessions
107			// with LastCheckpointID (needed for checkpoint ID reuse on subsequent commits).
108			// Clean up everything else: stale pre-state-machine sessions (empty phase),
109			// IDLE/ENDED sessions that were never condensed, etc.
110			shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
111			refName := plumbing.NewBranchReferenceName(shadowBranch)
112			if _, err := repo.Reference(refName, true); err != nil {
